    slots = (
        TalkSlot.objects.filter(submission__isnull=True, guid__isnull=True)
        .select_related("schedule")
        .order_by("schedule__published", "pk")
    )
    guid_by_key = {}
    schedules_claimed_by_key = {}
    for slot in slots:
        key = (
            slot.schedule.event_id,
            slot.slot_type,
            slot.room_id,
            str(slot.description),
            slot.start,
            slot.end,
        )
